using FactoryIQ.Agents; using FactoryIQ.Core.Models; using Xunit;
public sealed class AgentTests { [Fact] public async Task Workflow_Returns_Intelligence_And_Report(){ var o=new IncidentAnalysisOrchestrator(new IncidentIntakeAgent(),new IntelligenceAgent(new BundledSampleIQProvider()),new RootCauseAgent(),new ExecutiveReportAgent()); var r=await o.AnalyzeAsync(new IncidentInput("Wafer Inspection Tool Failure","Failure",["cpu spike","memory pressure"],new(){["cpu"]=96,["memory"]=91},DateTimeOffset.UtcNow,"High"), default); Assert.Equal(4,r.AgentContributions.Count); Assert.True(r.Confidence>.8); Assert.NotEmpty(r.Findings[0].Evidence[0].Sources); } }
